def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, 55.0))
        return float(min(budget, 1.0))

    opp_count = len(alive)
    total_players = opp_count + 1
    capacity = int(supply // WATER_REQ)

    prev_bids = []
    cindy_alive = False
    for oid, opp in alive:
        if oid == 'Cindy':
            cindy_alive = True
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0

    urgent = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1
    scarce = capacity < total_players
    very_scarce = capacity <= max(0, total_players - 2)

    if urgent:
        if cindy_alive:
            return float(min(budget, 76.0))
        return float(min(budget, max(58.0, highest_prev + 3.0)))

    if scarce:
        if cindy_alive:
            if very_scarce:
                return float(min(budget, 74.0))
            return float(min(budget, 6.0 if hp > 4 else 18.0))
        base = max(12.0, highest_prev + 2.0)
        if pressured:
            base = max(base, 32.0)
        return float(min(budget, base))

    if cindy_alive:
        if pressured:
            return float(min(budget, 8.0))
        return float(min(budget, 1.0))

    if highest_prev >= 60.0:
        return float(min(budget, 3.0 if hp > 4 else 20.0))
    if highest_prev >= 25.0:
        return float(min(budget, 10.0 if hp > 4 else 24.0))
    return float(min(budget, 5.0 if day < 8 else 9.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace to infer who is bidding aggressively.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict):
            bid = prev.get('bid', None)
            if bid is not None:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass
        elif isinstance(prev, list) and prev:
            last = prev[-1]
            if isinstance(last, dict) and last.get('bid', None) is not None:
                try:
                    prev_bids.append(float(last['bid']))
                except Exception:
                    pass

    # Fallback if no trace.
    if not prev_bids:
        base = DAILY_SALARY * (0.6 if supply >= 20 else 0.45)
        return max(0.0, min(my_budget, base))

    highest_prev_bid = max(prev_bids)

    # Pressure estimate: Cindy-like behavior if someone consistently bid near salary.
    aggressive = highest_prev_bid >= DAILY_SALARY * 0.75

    # If we are in danger (low hp or already missing water), raise bid.
    danger = (my_hp <= 2.5) or (my_no_water_days >= 2)

    # Supply affects how likely we are to win enough water; higher supply means we can bid less.
    supply_factor = 0.0
    if supply >= 22:
        supply_factor = -0.05
    elif supply <= 17:
        supply_factor = 0.05
    else:
        supply_factor = 0.0

    if aggressive:
        # Try to outbid the leader slightly, but cap to avoid bankruptcy.
        target = highest_prev_bid + 1.0
        if supply >= 22:
            target -= 2.0
        if my_hp > 3 and not danger:
            target -= 5.0
        # If budget is tight, scale down.
        cap = my_budget if my_budget > 0 else 0.0
        bid = min(target, cap)
        # Ensure non-negative and at least some participation.
        return max(0.0, bid)

    # Not aggressive overall: bid enough to secure water when needed.
    if danger:
        bid = DAILY_SALARY * (0.85 + supply_factor)
    else:
        bid = DAILY_SALARY * (0.55 + supply_factor)

    # If supply is low, slightly increase.
    if supply < 18:
        bid += 10.0

    # Final budget cap.
    return max(0.0, min(my_budget, bid))

